head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.contnId;
scwin.gLdMktTp = js_market;
scwin.bbsTypeCd = "7";
scwin.vScrenID = "ULDMGT06006.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_list_sync = function() {
    var url = "/lstinvstg/ListCommBoard.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=getList" + "&BBS_TP_CD=" + scwin.bbsTypeCd + "&LD_MKT_TP=" + $c.stf.getObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD) + "&SRCH_WORD=" + $c.stf.getObjectValue(txb_SRCH_WORD);
    dts_Grid.DataID = encodeURI(url);
    dts_Grid.reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.fn_setContnId = function(obj) {
    if (scwin.contnId != "input") {
        scwin.contnId = dts_Grid.getCellData(eval(obj), "CONTN_ID");
    }
};
scwin.fn_getContnId = function() {
    return scwin.contnId;
};
scwin.fn_input = async function() {
    await $c.frame.CreateDialogFrame("gform", "/lstmgt/ULDSTF06008.gfm", "상장지원 업무자료", 10, 10, 800, 500, "window");
};
scwin.fn_delete = function() {
    var gCnt = scwin.fn_selectCheckCnt(dts_Grid);
    if (gCnt == 0) {
        $c.win.alert("[삭제할 항목]을 선택하세요.");
        return;
    }
    sMsg = "삭제";
    if (window.confirm(gCnt + "건 삭제 하시겠습니까?")) {
        for (var k = 1; k <= dts_Grid.getTotalRow(); k++) {
            if (dts_Grid.getCellData(k, "CHECK") == "T") {

                // ********************************************************************
                // [WebSquare 전환 추가] 원본 소스와 비교 필요
                // 
                // ********************************************************************

                /*ORG SRC: dts_Grid.UserStatus(k) = TB_JOB_DELETE;*/
                X = TB_JOB_DELETE;
            }
        }
        trs_save.Action = "/ListPromtHistMgt.do?method=saveListPromtFAQ&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_Grid)";
        trs_save.Post();
    }
};
scwin.fn_selectCheckCnt = function(dtsObj) {
    var k = 0;
    for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
        if (dtsObj.getCellData(i, "CHECK") == "T") {
            k++;
        }
    }
    return k;
};
scwin.fn_setCheckBox = function(grdObj, dtsObj, bCheck) {
    var vcd = "";
    if (bCheck == '1') {
        vcd = "T";
    } else {
        vcd = "F";
    }
    grdObj.setBroadcast(false);
    for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
        dtsObj.setCellData(i, "CHECK", vcd);
    }
    grdObj.setBroadcast(true);
};
scwin.txb_SRCH_WORD_onkeydown = function() {
    if (event.keyCode == 13) {
        scwin.fn_list_sync();
    }
};
scwin.btn_Input_onclick = function() {
    scwin.contnId = 'input';
    scwin.fn_input();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_Grid_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid);
};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    scwin.contnId = '';
    if (colid != "CHECK") {
        scwin.fn_setContnId(row);
        scwin.fn_input();
    }
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.grd_Grid_OnHeadCheckClick = function(col, colid, bCheck) {
    $c.elw.fn_setCheckBox(grd_Grid, dts_Grid, bCheck);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.fn_list_sync();
};
scwin.trs_save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", sMsg));
    scwin.fn_list_sync();
};
scwin.trs_save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", sMsg));
};
scwin.grd_Grid_CanColumnPosChange = function(row, colid) {
    return true;
};
